1	import { test } from 'node:test';
2	import assert from 'node:assert/strict';
3	import { makeRepo, cleanup, declaredCheck } from '../../../../../engine-tests/helpers.mjs';
4	import { buildContext } from '../../../../../engine/checks/helpers/repo-context.mjs';
5	
6	const rule = declaredCheck('packs/claudinite-growth/skills/unattended-agents', 'in-session-github-access');
7	
8	// Co-located with the check it exercises (skills own their test-the-world checks).
9	const run = (root) => rule.run(buildContext({ root, mode: 'all' }));
10	
11	test('in-session-github-access: in-session code using injected MCP I/O passes', () => {
12	  const root = makeRepo({ changed: {
13	    'migrations/2026-01-01-demo/migration.mjs': 'export async function apply(io, r) { return io.commit(r, "main", [], "m"); }\n',
14	  } });
15	  try {
16	    assert.equal(run(root).length, 0);
17	  } finally { cleanup(root); }
18	});
19	
20	test('in-session-github-access: flags a GITHUB_TOKEN read in migration-pass code', () => {
21	  const root = makeRepo({ changed: {
22	    'migrations/2026-01-01-demo/migration.mjs': 'const token = process.env.GITHUB_TOKEN;\nexport const t = token;\n',
23	  } });
24	  try {
25	    const f = run(root);
26	    assert.equal(f.length, 1);
27	    assert.equal(f[0].severity, 'blocking');
28	    assert.equal(f[0].file, 'migrations/2026-01-01-demo/migration.mjs');
29	    assert.match(f[0].what, /REST token/);
30	  } finally { cleanup(root); }
31	});
32	
33	test('in-session-github-access: flags a REST client (makeGh / fleet-api) in a migration pass', () => {
34	  const file = 'migrations/some-pass.mjs';
35	  const root = makeRepo({ changed: {
36	    [file]: "import { makeGh } from '../packs/claudinite-fleet-sheepdog/fleet-api.mjs';\nexport const gh = makeGh('t');\n",
37	  } });
38	  try {
39	    const f = run(root);
40	    assert.ok(f.length >= 1);
41	    assert.ok(f.every((x) => x.file === file));
42	    assert.match(f[0].what, /REST client/);
43	  } finally { cleanup(root); }
44	});
45	
46	test('in-session-github-access: a run_daily/ path is no longer an in-session surface', () => {
47	  // The central planner that dispatched run_daily descriptors into an MCP-only
48	  // session retired with #394, and no repo carries them any more — so the scope
49	  // arm went with it. Drift guard: if run_daily/ is ever re-added to IN_SESSION
50	  // without a planner to justify it, this fails.
51	  const root = makeRepo({ changed: {
52	    '.claudinite/local/packs/x/run_daily/task.mjs': 'const t = process.env.GITHUB_TOKEN;\nexport const y = t;\n',
53	  } });
54	  try {
55	    assert.equal(run(root).length, 0);
56	  } finally { cleanup(root); }
57	});
58	
59	test('in-session-github-access: a scheduled task\'s preprocessing worker keeps its REST client', () => {
60	  // code-work runs Action-side as a subprocess with an injected
61	  // GITHUB_TOKEN — the one sanctioned non-MCP surface — so tasks/ is deliberately
62	  // outside the in-session scope.
63	  const root = makeRepo({ changed: {
64	    'packs/claudinite-lifecycle/tasks/update/worker.mjs': "const t = process.env.GITHUB_TOKEN;\nconst r = await fetch('https://api.github.com/repos/x');\nexport const y = [t, r];\n",
